#include <memory>
#include <cassert>
#include <type_traits>
#include <utility>
void create(int **p) { *p = new int(7); }
void replace(int **p) {
    delete *p;
    *p = new int(9);
}
int main() {
    std::unique_ptr<int> pointer;
    {
        auto output = std::out_ptr(pointer);
        int **raw = output;
        create(raw);
    }
    assert(*pointer == 7);
    {
        auto inputOutput = std::inout_ptr(pointer);
        int **raw = inputOutput;
        replace(raw);
    }
    assert(*pointer == 9);
}
